sparql_tries.sparql:
SELECT DISTINCT ?modelYear WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber "26V430000" ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model ;
           rc:modelYear ?modelYear .
  ?model rc:name "TELLURIDE" ;
         rc:ofMake ?make .
  ?make rc:name "KIA" .
}
ORDER BY ?modelYear

SELECT DISTINCT ?campaignNumber ?makeName ?modelName ?date WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber ;
            rc:doNotDrive true ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make ;
         rc:name ?modelName .
  ?make rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA", "GENESIS"))
  OPTIONAL { ?campaign rc:reportReceivedDate ?date }
}
ORDER BY DESC(?date) ?campaignNumber

SELECT DISTINCT ?campaignNumber ?initiatedBy ?date WHERE {
  ?recall a rc:RecallCampaign ;
          rc:campaignNumber ?campaignNumber ;
          rc:initiatedBy ?initiatedBy .
  OPTIONAL { ?recall rc:reportReceivedDate ?date }
  FILTER(CONTAINS(UCASE(STR(?initiatedBy)), "OVSC"))
}
ORDER BY DESC(?date) ?campaignNumber

SELECT DISTINCT ?modelName ?makeName WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:affectsComponent ?comp ;
            rc:affects ?variant .
  ?comp rc:name "SERVICE BRAKES, HYDRAULIC:ANTILOCK/TRACTION CONTROL/ELECTRONIC LIMITED SLIP:CONTROL UNIT/MODULE" .
  ?variant rc:ofModel ?model .
  ?model rc:name ?modelName ;
         rc:ofMake ?make .
  ?make rc:name ?makeName .
}
ORDER BY ?makeName ?modelName

SELECT ?componentName (COUNT(DISTINCT ?c) AS ?campaignCount)
WHERE {
  ?comp a rc:Component ;
        rc:name ?componentName .
  FILTER EXISTS { ?comp skos:broader ?parent }
  FILTER EXISTS {
    ?c1 rc:affectsComponent ?comp ;
        rc:affects/rc:ofModel/rc:ofMake/rc:name "HYUNDAI" .
  }
  FILTER EXISTS {
    ?c2 rc:affectsComponent ?comp ;
        rc:affects/rc:ofModel/rc:ofMake/rc:name "KIA" .
  }
  ?c rc:affectsComponent ?comp ;
     rc:affects/rc:ofModel/rc:ofMake/rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA"))
}
GROUP BY ?componentName
ORDER BY DESC(?campaignCount)
LIMIT 1

SELECT ?campaignNumber (COUNT(DISTINCT ?make) AS ?makeCount) (GROUP_CONCAT(DISTINCT ?makeName; separator=", ") AS ?makes)
WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
}
GROUP BY ?campaignNumber
HAVING (COUNT(DISTINCT ?make) > 1)
ORDER BY DESC(?makeCount) ?campaignNumber

SELECT DISTINCT ?campaignNumber ?date WHERE {
  ?make a rc:Make ; rc:name "HYUNDAI" .
  ?model a rc:VehicleModel ; rc:ofMake ?make ; rc:name "SANTA FE" .
  ?variant a rc:VehicleVariant ; rc:ofModel ?model ; rc:modelYear ?year .
  FILTER(STR(?year) = "2021")
  ?campaign a rc:RecallCampaign ; rc:affects ?variant ; rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?campaign rc:reportReceivedDate ?date }
}
ORDER BY ?date ?campaignNumber

SELECT DISTINCT ?modelName ?componentName WHERE {
  ?kiaCampaign rc:affects ?kiaVariant ;
               rc:affectsComponent ?component .
  ?kiaVariant rc:ofModel ?kiaModel .
  ?kiaModel rc:name "TELLURIDE" ;
            rc:ofMake ?kiaMake .
  ?kiaMake rc:name "KIA" .
  ?component skos:broader ?parent ;
             rc:name ?componentName .

  ?genCampaign rc:affects ?genVariant ;
               rc:affectsComponent ?component .
  ?genVariant rc:ofModel ?genModel .
  ?genModel rc:ofMake ?genMake ;
            rc:name ?modelName .
  ?genMake rc:name "GENESIS" .
}
ORDER BY ?modelName ?componentName

SELECT ?modelName ?makeName (COUNT(DISTINCT ?campaign) AS ?campaignCount) WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:name ?modelName .
  OPTIONAL { ?model rc:ofMake ?make . ?make rc:name ?makeName . }
}
GROUP BY ?modelName ?makeName
ORDER BY DESC(?campaignCount)
LIMIT 1

SELECT (COUNT(DISTINCT ?campaign) AS ?count) WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:reportReceivedDate ?date ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA", "GENESIS"))
  FILTER(YEAR(?date) = 2023)
}

SELECT ?topName (COUNT(DISTINCT ?model) AS ?modelCount) WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:affectsComponent ?component ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?component skos:broader* ?top .
  ?top a rc:Component ; rc:name ?topName .
  FILTER NOT EXISTS { ?top skos:broader ?parent . }
}
GROUP BY ?topName
ORDER BY DESC(?modelCount)
LIMIT 1

SELECT ?topName (COUNT(DISTINCT ?c) AS ?campaigns) WHERE {
  ?c a rc:RecallCampaign ;
     rc:affects ?v ;
     rc:affectsComponent ?comp .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name "GENESIS" .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?x }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?campaigns)
LIMIT 1

SELECT (COUNT(DISTINCT ?year) AS ?yearCount) WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model ;
           rc:modelYear ?year .
  ?model rc:name "SONATA" ;
         rc:ofMake ?make .
  ?make rc:name "HYUNDAI" .
}

SELECT ?year (COUNT(DISTINCT ?campaign) AS ?recallCount)
WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:reportReceivedDate ?date ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA", "GENESIS"))
  BIND(YEAR(?date) AS ?year)
}
GROUP BY ?year
ORDER BY DESC(?recallCount) ?year

SELECT DISTINCT ?campaignNumber ?manufacturer ?componentName ?reportReceivedDate WHERE {
  ?recall a rc:RecallCampaign ;
          rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?recall rc:filedBy ?mfr . ?mfr rc:name ?manufacturer . }
  OPTIONAL { ?recall rc:reportReceivedDate ?reportReceivedDate . }
  OPTIONAL { ?recall rc:affectsComponent ?comp . ?comp rc:name ?componentName . }
  OPTIONAL { ?recall rc:defectSummary ?defect . }
  OPTIONAL { ?recall rc:consequenceSummary ?consequence . }
  FILTER (
    REGEX(COALESCE(?componentName, ""), "HYDROGEN", "i") ||
    ( REGEX(COALESCE(?defect, ""), "hydrogen", "i") &&
      REGEX(CONCAT(COALESCE(?defect, ""), " ", COALESCE(?consequence, "")), "leak|detect", "i") )
  )
}
ORDER BY DESC(?reportReceivedDate) ?campaignNumber

SELECT DISTINCT ?campaignNumber ?date ?mfr WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?r rc:reportReceivedDate ?date }
  OPTIONAL { ?r rc:filedBy ?m . ?m rc:name ?mfr }
  {
    ?r rc:defectSummary ?txt .
    FILTER(REGEX(?txt, "ICCU|Integrated Charging Control Unit", "i"))
  } UNION {
    ?r rc:affectsComponent ?c . ?c rc:name ?cname .
    FILTER(REGEX(?cname, "ICCU|INTEGRATED CHARGING CONTROL", "i"))
  }
}
ORDER BY ?date ?campaignNumber

SELECT DISTINCT ?campaignNumber ?defectSummary ?rootCause
WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?campaign rc:defectSummary ?defectSummary . }
  OPTIONAL { ?campaign rc:rootCause ?rootCause . }
  BIND(LCASE(CONCAT(COALESCE(?defectSummary, ""), " ", COALESCE(?rootCause, ""))) AS ?text)
  FILTER(
    (CONTAINS(?text, "water") || CONTAINS(?text, "moisture"))
    && (CONTAINS(?text, "tow") || CONTAINS(?text, "trailer") || CONTAINS(?text, "hitch"))
    && (CONTAINS(?text, "module") || CONTAINS(?text, "control unit") || CONTAINS(?text, "ecu") || CONTAINS(?text, "wiring") || CONTAINS(?text, "harness") || CONTAINS(?text, "connector"))
  )
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber ?defect WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:defectSummary ?defect .
  FILTER(REGEX(?defect, "connecting rod bearing", "i") && REGEX(?defect, "wear", "i"))
}
ORDER BY ?campaignNumber
